#include "../platform/windows-video-compositor/video_compositor.h"
#include <dxgi1_2.h>
#include <iostream>
#include <stdexcept>
using namespace viewflow::windows;
using Microsoft::WRL::ComPtr;
static void check(bool ok,const char* what){if(!ok)throw std::runtime_error(what);}
static void hr(HRESULT r){check(SUCCEEDED(r),"D3D call failed");}
struct Gpu {
  ComPtr<ID3D11Device> device; ComPtr<ID3D11DeviceContext> context;
  Gpu(){hr(D3D11CreateDevice(nullptr,D3D_DRIVER_TYPE_HARDWARE,nullptr,D3D11_CREATE_DEVICE_BGRA_SUPPORT,nullptr,0,D3D11_SDK_VERSION,&device,nullptr,&context));
    ComPtr<IDXGIDevice> dx;hr(device.As(&dx));ComPtr<IDXGIAdapter> a;hr(dx->GetAdapter(&a));DXGI_ADAPTER_DESC desc{};hr(a->GetDesc(&desc));std::cout<<"hardware_vendor="<<desc.VendorId<<" device="<<desc.DeviceId<<"\n";}
  ComPtr<ID3D11Texture2D> texture(UINT w,UINT h){D3D11_TEXTURE2D_DESC d{};d.Width=w;d.Height=h;d.MipLevels=d.ArraySize=d.SampleDesc.Count=1;d.Format=DXGI_FORMAT_B8G8R8A8_UNORM;d.Usage=D3D11_USAGE_DEFAULT;ComPtr<ID3D11Texture2D> t;hr(device->CreateTexture2D(&d,nullptr,&t));return t;}
  CompositedFrame acquire(OutputSurfacePool& pool,uint64_t id,UINT w=3840,UINT h=2400,bool expected_reuse=false){std::shared_ptr<OutputSurface>s;bool reused{};hr(pool.Acquire(device.Get(),w,h,&s,&reused));check(reused==expected_reuse,"unexpected reuse decision");return {id,w,h,s->texture,{},{},s};}
  void clear(const CompositedFrame& f,unsigned color){float c[4]{(color&1)?128.0f/255:0,(color&2)?128.0f/255:0,(color&4)?128.0f/255:0,128.0f/255};context->ClearRenderTargetView(f.output_owner->view.Get(),c);}
  void verify(ID3D11Texture2D* texture,unsigned color){D3D11_TEXTURE2D_DESC d{};texture->GetDesc(&d);d.Usage=D3D11_USAGE_STAGING;d.BindFlags=0;d.CPUAccessFlags=D3D11_CPU_ACCESS_READ;d.MiscFlags=0;ComPtr<ID3D11Texture2D> t;hr(device->CreateTexture2D(&d,nullptr,&t));context->CopyResource(t.Get(),texture);D3D11_MAPPED_SUBRESOURCE m{};hr(context->Map(t.Get(),0,D3D11_MAP_READ,0,&m));bool same=true;const unsigned char expected[]{static_cast<unsigned char>((color&4)?128:0),static_cast<unsigned char>((color&2)?128:0),static_cast<unsigned char>((color&1)?128:0),128};for(UINT y=0;y<d.Height;++y){auto p=static_cast<const unsigned char*>(m.pData)+size_t(y)*m.RowPitch;for(UINT x=0;x<d.Width;++x)for(int k=0;k<4;++k)same=same&&(p[4*x+k]==expected[k]);}context->Unmap(t.Get(),0);check(same,"pixel mismatch");}
};
int main(){try{Gpu g;
  {OutputSurfacePool p;std::vector<CompositedFrame> held;for(unsigned i=0;i<5;++i){held.push_back(g.acquire(p,i+1));g.clear(held.back(),i);for(unsigned j=0;j<i;++j)check(held[i].premultiplied_bgra.Get()!=held[j].premultiplied_bgra.Get(),"leased output recycled");}auto n=p.counters();check(n.acquisitions==5&&n.created==5&&n.reused==0&&n.fallback==1&&n.slots==4,"pressure counters");for(unsigned i=0;i<5;++i)g.verify(held[i].premultiplied_bgra.Get(),i);std::cout<<"PASS retained_4k_frames=5 full_pool_uncached_fallback=1 exact_bgra_bytes="<<5ull*3840*2400*4<<"\n";}
  {OutputSurfacePool p;auto parent=g.acquire(p,10);g.clear(parent,3);CompositedFrame crop;hr(MakeCompositedRegion(parent,{16,32,128,64},&crop));auto original=parent.premultiplied_bgra.Get();parent={};auto next=g.acquire(p,11);check(next.premultiplied_bgra.Get()!=original,"crop lost pool owner");g.clear(next,6);auto dst=g.texture(128,64);hr(CopyCompositedRegion(g.context.Get(),crop,dst.Get(),0,0));check(crop.frame_identity==10&&crop.width==128&&crop.height==64,"crop identity/geometry");g.verify(dst.Get(),3);crop={};auto reuse=g.acquire(p,12,3840,2400,true);check(reuse.premultiplied_bgra.Get()==original,"released crop not reused");std::cout<<"PASS crop_retains_parent_owner_and_identity exact_crop_bgra=32768\n";}
  {OutputSurfacePool p;for(unsigned i=0;i<16;++i){auto old=g.acquire(p,100+i*2,3840,2400,i!=0);g.clear(old,i%8);auto dst=g.texture(3840,2400);auto original=old.premultiplied_bgra.Get();hr(CopyCompositedRegion(g.context.Get(),old,dst.Get(),0,0));old={};auto newer=g.acquire(p,101+i*2,3840,2400,true);check(newer.premultiplied_bgra.Get()==original,"queued copy test did not reuse source");g.clear(newer,(i+1)%8);g.verify(dst.Get(),i%8);g.verify(newer.premultiplied_bgra.Get(),(i+1)%8);}auto n=p.counters();check(n.acquisitions==32&&n.created==1&&n.reused==31&&n.fallback==0,"queued counters");std::cout<<"PASS queued_copy_before_reuse_without_cpu_wait=16 exact_4k_bgra_bytes="<<32ull*3840*2400*4<<"\n";}
  {OutputSurfacePool p;auto original=g.acquire(p,200);g.clear(original,7);std::vector<CompositedFrame> sizes;for(unsigned i=0;i<4;++i){sizes.push_back(g.acquire(p,201+i,64+i*16,32+i*16));g.clear(sizes.back(),i);}g.verify(original.premultiplied_bgra.Get(),7);for(unsigned i=0;i<4;++i)g.verify(sizes[i].premultiplied_bgra.Get(),i);auto n=p.counters();check(n.created==5&&n.fallback==1&&n.slots==4,"geometry pressure counters");sizes.clear();auto changed=g.acquire(p,205,128,96);g.clear(changed,2);g.verify(changed.premultiplied_bgra.Get(),2);g.verify(original.premultiplied_bgra.Get(),7);std::cout<<"PASS changing_geometry_preserves_leased_4k_frame_and_fallback\n";}
  {OutputSurfacePool p;auto old=g.acquire(p,300,64,32);g.clear(old,1);old={};Gpu second;auto fresh=second.acquire(p,301,64,32);ComPtr<ID3D11Device> owner;fresh.premultiplied_bgra->GetDevice(&owner);check(owner.Get()==second.device.Get(),"wrong device reused");second.clear(fresh,4);second.verify(fresh.premultiplied_bgra.Get(),4);std::cout<<"PASS device_change_allocates_matching_device\n";}
  std::cout<<"PASS output_surface_pool_all_tests\n";return 0;
}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<"\n";return 1;}}
